-- V010: usage records get a server-side identity.
-- request_id is chosen by the client, so it cannot be the uniqueness key of the ledger.
-- A client that reuses one id was recorded once and its daily plan quota never advanced.
-- record_id is generated by the server for every record and keeps retries idempotent.
ALTER TABLE ai_usage_records DROP CONSTRAINT ai_usage_records_client_id_request_id_key;
ALTER TABLE ai_usage_records ADD COLUMN record_id UUID;
UPDATE ai_usage_records SET record_id = gen_random_uuid() WHERE record_id IS NULL;
ALTER TABLE ai_usage_records ALTER COLUMN record_id SET NOT NULL;
CREATE UNIQUE INDEX uq_ai_usage_record_id ON ai_usage_records(record_id);
CREATE INDEX idx_ai_usage_client_request ON ai_usage_records(client_id, request_id);
